/**
 * Bulk issue imports: the replay record keyed per workspace by import key, and
 * the single transaction that writes a whole batch.
 */
import { and, eq, isNull, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import {
  getDb,
  issueImports,
  issueLabels,
  issues,
  labels,
  members,
  users,
} from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { IssueId, OrgId, ProjectId, UserId } from "@/types/common";
import type { IssuePriority, IssueStatus } from "@/types/issue";

export type IssueImportRecord = {
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly issueIds: readonly IssueId[];
};

export type PreparedImportRow = {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly labelNames: readonly string[];
  readonly dueAt: string | null;
};

export async function findImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  if (!row) return null;
  return {
    projectId: row.projectId as ProjectId,
    importKey: row.importKey,
    issueIds: JSON.parse(row.issueIds) as IssueId[],
  };
}

/** Lower-cased email → user id for the org's current active members. */
export async function activeMemberIdsByEmail(
  orgId: OrgId,
): Promise<ReadonlyMap<string, UserId>> {
  const rows = getDb()
    .select({ userId: members.userId, email: users.email })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        isNull(members.archivedAt),
      ),
    )
    .all();
  return new Map(
    rows.map((row) => [row.email.toLowerCase(), row.userId as UserId]),
  );
}

/**
 * Writes the batch atomically: missing labels, the issues numbered in file
 * order after the project's highest number, their label links and the replay
 * record. Returns the new issue ids in file order.
 */
export async function insertImport(
  orgId: OrgId,
  projectId: ProjectId,
  importKey: string,
  authorId: UserId,
  rows: readonly PreparedImportRow[],
): Promise<readonly IssueId[]> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());

  return db.transaction((tx) => {
    const labelIdByName = new Map<string, string>();
    for (const label of tx
      .select({ id: labels.id, name: labels.name })
      .from(labels)
      .where(orgPredicate(labels.orgId, orgId))
      .all()) {
      labelIdByName.set(label.name, label.id);
    }

    for (const row of rows) {
      for (const name of row.labelNames) {
        if (labelIdByName.has(name)) continue;
        const id = newId();
        tx.insert(labels)
          .values({
            id,
            orgId,
            name,
            color: "#94a3b8",
            description: null,
            createdAt: stamp,
            updatedAt: stamp,
          })
          .run();
        labelIdByName.set(name, id);
      }
    }

    const max = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(orgPredicate(issues.orgId, orgId), eq(issues.projectId, projectId)),
      )
      .get();
    let number = max?.value ?? 0;

    const issueIds: IssueId[] = [];
    for (const row of rows) {
      const id = newId() as IssueId;
      number += 1;
      tx.insert(issues)
        .values({
          id,
          orgId,
          projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .run();

      const labelIds = [...new Set(row.labelNames)].map(
        (name) => labelIdByName.get(name) as string,
      );
      if (labelIds.length > 0) {
        tx.insert(issueLabels)
          .values(labelIds.map((labelId) => ({ orgId, issueId: id, labelId })))
          .run();
      }
      issueIds.push(id);
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId,
        projectId,
        importKey,
        issueIds: JSON.stringify(issueIds),
        createdBy: authorId,
        createdAt: stamp,
      })
      .run();

    return issueIds;
  });
}
