  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const memberIds = await importRepo.activeMemberIdsByEmail(input.orgId);
  const issueIds = await importRepo.insertImport(
    input.orgId,
    input.projectId,
    input.importKey,
    actor.userId,
    input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (memberIds.get(row.assigneeEmail.toLowerCase()) ?? null),
      labelNames: row.labels,
      dueAt: row.dueAt,
    })),
  );

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds,
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: await loadIssues(input.orgId, issueIds),
    replayed: false,
  };
}

async function loadIssues(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  const found: Issue[] = [];
  for (const id of issueIds) {
    const issue = await issueRepo.findIssueById(orgId, id);
    if (issue) found.push(issue);
  }
  return found;
}

